ALTER TABLE user ADD COLUMN deleted_at TEXT;
ALTER TABLE user ADD COLUMN deleted_by TEXT REFERENCES user(id);
ALTER TABLE clients ADD COLUMN deleted_at TEXT;
ALTER TABLE clients ADD COLUMN deleted_by TEXT REFERENCES user(id);
ALTER TABLE products ADD COLUMN deleted_at TEXT;
ALTER TABLE products ADD COLUMN deleted_by TEXT REFERENCES user(id);
ALTER TABLE exchange_rates ADD COLUMN deleted_at TEXT;
ALTER TABLE exchange_rates ADD COLUMN deleted_by TEXT REFERENCES user(id);
ALTER TABLE orders ADD COLUMN deleted_at TEXT;
ALTER TABLE orders ADD COLUMN deleted_by TEXT REFERENCES user(id);
ALTER TABLE routes ADD COLUMN deleted_at TEXT;
ALTER TABLE routes ADD COLUMN deleted_by TEXT REFERENCES user(id);
ALTER TABLE visits ADD COLUMN deleted_at TEXT;
ALTER TABLE visits ADD COLUMN deleted_by TEXT REFERENCES user(id);
ALTER TABLE visits ADD COLUMN deleted_with_route INTEGER NOT NULL DEFAULT 0;
CREATE INDEX visit_route ON visits(route_id,route_position);
CREATE INDEX visit_client_pending ON visits(client_id) WHERE deleted_at IS NULL AND status='programada';
CREATE INDEX visit_seller_pending ON visits(seller_id) WHERE deleted_at IS NULL AND status='programada';
DROP INDEX visit_no_duplicate;
CREATE UNIQUE INDEX visit_no_duplicate ON visits(client_id,seller_id,scheduled_at) WHERE deleted_at IS NULL;
DROP TRIGGER visit_instant_guard;
CREATE TRIGGER visit_instant_guard BEFORE INSERT ON visits WHEN new.deleted_at IS NULL AND EXISTS(SELECT 1 FROM visits WHERE deleted_at IS NULL AND client_id=new.client_id AND seller_id=new.seller_id AND julianday(scheduled_at)=julianday(new.scheduled_at)) BEGIN SELECT RAISE(ABORT,'VISIT_DUPLICATE'); END;
CREATE TRIGGER visit_restore_collision BEFORE UPDATE OF deleted_at ON visits WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL AND EXISTS(SELECT 1 FROM visits WHERE deleted_at IS NULL AND client_id=new.client_id AND seller_id=new.seller_id AND julianday(scheduled_at)=julianday(new.scheduled_at)) BEGIN SELECT RAISE(ABORT,'VISIT_DUPLICATE'); END;
DROP TRIGGER last_admin;
CREATE TRIGGER last_admin BEFORE UPDATE OF role,active,banned,deleted_at ON user WHEN old.role='administracion' AND old.active=1 AND coalesce(old.banned,0)=0 AND old.deleted_at IS NULL AND (new.role<>'administracion' OR new.active=0 OR coalesce(new.banned,0)=1 OR new.deleted_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM user WHERE id<>old.id AND role='administracion' AND active=1 AND coalesce(banned,0)=0 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'LAST_ADMIN'); END;
CREATE TRIGGER user_trash_guard BEFORE UPDATE OF deleted_at ON user WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL AND (EXISTS(SELECT 1 FROM visits WHERE seller_id=old.id AND deleted_at IS NULL AND status='programada') OR EXISTS(SELECT 1 FROM clients WHERE seller_id=old.id AND deleted_at IS NULL)) BEGIN SELECT RAISE(ABORT,'TRASH_USER_DEPENDENCIES'); END;
CREATE TRIGGER client_trash_guard BEFORE UPDATE OF deleted_at ON clients WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL AND EXISTS(SELECT 1 FROM visits WHERE client_id=old.id AND deleted_at IS NULL AND status='programada') BEGIN SELECT RAISE(ABORT,'TRASH_CLIENT_DEPENDENCIES'); END;
CREATE TRIGGER revoke_trashed_user AFTER UPDATE OF deleted_at ON user WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN DELETE FROM session WHERE userId=new.id; END;
CREATE TRIGGER trashed_user_session BEFORE INSERT ON session WHEN EXISTS(SELECT 1 FROM user WHERE id=new.userId AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER seller_assignment_insert BEFORE INSERT ON clients WHEN EXISTS(SELECT 1 FROM user WHERE id=new.seller_id AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'TRASH_RESTORE_DEPENDENCY'); END;
CREATE TRIGGER seller_assignment_update BEFORE UPDATE OF seller_id,deleted_at ON clients WHEN new.deleted_at IS NULL AND new.seller_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM user WHERE id=new.seller_id AND deleted_at IS NULL AND active=1 AND coalesce(banned,0)=0 AND role='vendedor') BEGIN SELECT RAISE(ABORT,'TRASH_RESTORE_DEPENDENCY'); END;
CREATE TRIGGER order_trash_guard BEFORE UPDATE OF deleted_at ON orders WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL AND old.status<>'anulado' BEGIN SELECT RAISE(ABORT,'TRASH_ORDER_STATE'); END;
CREATE TRIGGER order_trash_dependencies BEFORE INSERT ON orders WHEN EXISTS(SELECT 1 FROM clients WHERE id=new.client_id AND deleted_at IS NOT NULL) OR EXISTS(SELECT 1 FROM user WHERE id=new.author_id AND deleted_at IS NOT NULL) OR (new.currency<>'USD' AND (new.rate_id IS NULL OR new.rate_id IS NOT (SELECT id FROM exchange_rates WHERE currency=new.currency AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 1))) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER product_trash_guard BEFORE INSERT ON order_items WHEN EXISTS(SELECT 1 FROM products WHERE id=new.product_id AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER visit_closed_trash BEFORE UPDATE OF deleted_at ON visits WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL AND old.status<>'programada' BEGIN SELECT RAISE(ABORT,'TRASH_VISIT_STATE'); END;
CREATE TRIGGER visit_last_stop BEFORE UPDATE OF deleted_at ON visits WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL AND new.deleted_with_route=0 AND old.route_id IS NOT NULL AND EXISTS(SELECT 1 FROM routes WHERE id=old.route_id AND deleted_at IS NULL) AND NOT EXISTS(SELECT 1 FROM visits WHERE route_id=old.route_id AND id<>old.id AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'TRASH_LAST_STOP'); END;
CREATE TRIGGER visit_active_dependencies BEFORE INSERT ON visits WHEN EXISTS(SELECT 1 FROM clients WHERE id=new.client_id AND deleted_at IS NOT NULL) OR EXISTS(SELECT 1 FROM user WHERE id=new.seller_id AND deleted_at IS NOT NULL) OR EXISTS(SELECT 1 FROM routes WHERE id=new.route_id AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER visit_restore_dependencies BEFORE UPDATE OF deleted_at ON visits WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL AND (NOT EXISTS(SELECT 1 FROM clients c JOIN user u ON u.id=new.seller_id WHERE c.id=new.client_id AND c.deleted_at IS NULL AND c.active=1 AND c.seller_id=new.seller_id AND u.deleted_at IS NULL AND u.role='vendedor' AND u.active=1 AND coalesce(u.banned,0)=0) OR (new.route_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM routes WHERE id=new.route_id AND deleted_at IS NULL AND seller_id=new.seller_id AND date=date(new.scheduled_at,'-4 hours')))) BEGIN SELECT RAISE(ABORT,'TRASH_RESTORE_DEPENDENCY'); END;
CREATE TRIGGER visit_completion_guard BEFORE INSERT ON visit_completions WHEN NOT EXISTS(SELECT 1 FROM visits WHERE id=new.visit_id AND deleted_at IS NULL AND status='programada') BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER visit_order_guard BEFORE UPDATE OF order_id ON visits WHEN EXISTS(SELECT 1 FROM orders WHERE id=new.order_id AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER route_delete_guard BEFORE UPDATE OF deleted_at ON routes WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL AND EXISTS(SELECT 1 FROM visits WHERE route_id=old.id AND status<>'programada') BEGIN SELECT RAISE(ABORT,'ROUTE_STARTED'); END;
CREATE TRIGGER route_trash_stops AFTER UPDATE OF deleted_at ON routes WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN UPDATE visits SET deleted_at=new.deleted_at,deleted_by=new.deleted_by,deleted_with_route=1 WHERE route_id=new.id AND deleted_at IS NULL; END;
CREATE TRIGGER route_restore_stops AFTER UPDATE OF deleted_at ON routes WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL BEGIN UPDATE visits SET deleted_at=NULL,deleted_by=NULL,deleted_with_route=0 WHERE route_id=new.id AND deleted_with_route=1; END;
CREATE TRIGGER route_trash_seller_insert BEFORE INSERT ON routes WHEN EXISTS(SELECT 1 FROM user WHERE id=new.seller_id AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER route_trash_seller_update BEFORE UPDATE OF deleted_at,seller_id ON routes WHEN new.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM user WHERE id=new.seller_id AND deleted_at IS NULL AND active=1 AND coalesce(banned,0)=0 AND role='vendedor') BEGIN SELECT RAISE(ABORT,'TRASH_RESTORE_DEPENDENCY'); END;
CREATE TRIGGER audit_trash_user AFTER UPDATE OF deleted_at ON user WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','usuario',new.id,new.deleted_at); END;
CREATE TRIGGER audit_trash_clients AFTER UPDATE OF deleted_at ON clients WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','cliente',new.id,new.deleted_at); END;
CREATE TRIGGER audit_trash_products AFTER UPDATE OF deleted_at ON products WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','producto',new.id,new.deleted_at); END;
CREATE TRIGGER audit_trash_exchange_rates AFTER UPDATE OF deleted_at ON exchange_rates WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','tasa',new.id,new.deleted_at); END;
CREATE TRIGGER audit_trash_routes AFTER UPDATE OF deleted_at ON routes WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','ruta',new.id,new.deleted_at); END;
CREATE TRIGGER audit_trash_visits AFTER UPDATE OF deleted_at ON visits WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','visita',new.id,new.deleted_at); END;
CREATE TRIGGER audit_trash_orders AFTER UPDATE OF deleted_at ON orders WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','pedido',new.id,new.deleted_at); END;
CREATE TRIGGER route_trashed_edit BEFORE UPDATE OF name,seller_id,date,series_id,recurrence_json ON routes WHEN old.deleted_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE TRIGGER visit_route_client_restore BEFORE UPDATE OF deleted_at ON visits WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL AND new.route_id IS NOT NULL AND EXISTS(SELECT 1 FROM visits WHERE route_id=new.route_id AND client_id=new.client_id AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'TRASH_ROUTE_CLIENT'); END;
CREATE TRIGGER account_trashed_password BEFORE UPDATE OF password ON account WHEN EXISTS(SELECT 1 FROM user WHERE id=old.userId AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'TRASHED_RECORD'); END;
CREATE INDEX trash_user_date ON user(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
CREATE INDEX trash_clients_date ON clients(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
CREATE INDEX trash_products_date ON products(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
CREATE INDEX trash_exchange_rates_date ON exchange_rates(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
CREATE INDEX trash_routes_date ON routes(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
CREATE INDEX trash_visits_date ON visits(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
CREATE INDEX trash_orders_date ON orders(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
